window.MONSTER_CHUNK_62 = [{"name":"Giant Tarantula","cr":8,"xp":4800,"alignment":"N","size":"Gargantuan","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":21,"ac_touch":7,"ac_flat_footed":20,"ac_mods":"+1 Dex, +14 natural, -4 size","hp":115,"hd":"10d8+70","hdvalue":10,"fort":14,"ref":4,"will":3,"defensive_abilities":["barbed hairs"],"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"bite +15 (3d6+18 plus poison)","ranged":"barbed hairs +4 touch (nausea)","space":"20 ft.","reach":"20 ft.","strength":35,"dexterity":13,"constitution":24,"wisdom":10,"charisma":2,"baseatk":7,"cmb":23,"cmd":34,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":28},{"skill":"Perception","value":4},{"skill":"Stealth","value":-7,"special":"-3 in webs"}],"environments":["any forests"],"organizations":["solitary","pair","colony (3-8)"],"treasure":"incidental","description_visual":"A massive tarantula covered in bristly hairs strides forward with deliberate steps, its eight eyes scanning for prey.","group":"Spider","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Barbed Hairs","kind":"Ex","details":"A tarantula can throw barbed hairs from its back at a creature as a ranged touch attack (range increment 20 ft.). A creature struck by these hairs must make a DC 22 Fort save or be nauseated for 1d6 rounds. A creature that attacks a giant tarantula with a non-reach melee weapon must make a DC 22 Reflex save to avoid being struck by these hairs. The save DC is Con-based."},{"type":"Poison","kind":"Ex","details":"Bite- injury; save Fort DC 24; frequency 1/ round for 6 rounds; effect 1d6 Str; cure 2 consecutive saves. Save DC is Con-based with a +2 racial bonus."}],"description":"A tarantula doesn't use a web to ensnare prey, though it may spin a trip wire to signal an alert when something approaches its burrow. These spiders grab with their appendages, inject paralyzing venom, and dispatch their unfortunate victims with their fangs. They also secrete digestive enzymes to liquefy their victims' bodies so that they can suck them up through their straw-like mouth openings. After a large meal, the tarantula may not need to eat for a month.","ecology":"","habitat_society":""},{"name":"Girtablilu","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"monstrous humanoid","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"ac":22,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+2 armor, +2 Dex, +1 dodge, +8 natural, -1 size","hp":105,"hd":"10d10+50","hdvalue":10,"fort":8,"ref":11,"will":9,"speed":[{"type":"land","speed":50}],"melee":"mwk spear +15 (1d8+7/x3), 2 claws +9 (1d6+2 plus grab), sting +9 (1d6+2 plus poison)","ranged":"mwk spear +12 (1d8+5/x3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"1d6+5"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon nature's ally V","details":"1d3 giant scorpions"}]}],"strength":20,"dexterity":15,"constitution":21,"intelligence":10,"wisdom":14,"charisma":11,"baseatk":10,"cmb":16,"cmb_special":"+4 vs. grapple","cmd":29,"cmd_special":"+12 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Mobility"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":17},{"skill":"Craft (any one)","value":8},{"skill":"Knowledge (history)","value":5},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":7},{"skill":"Stealth","value":10},{"skill":"Survival","value":15}],"languages":["Common","Girtablilu"],"sq":[{"type":"scorpion empathy","details":"+10"},{"type":"undersized weapons"}],"environments":["warm deserts"],"organizations":["solitary","pair","patrol (3-5 plus 2-4 giant scorpions)","cult (6-14 plus 3-6 temple guardians of 3rd level, 1 cleric or oracle leader of 6th level, and 4-9 giant scorpions)"],"treasure":"standard (leather armor, masterwork spear)","description_visual":"The body of a spear-wielding woman rises from the front of this monstrously huge scorpion.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 20; frequency 1/round for 6 rounds; effect 1d4 Dex; cure 2 consecutive saves."},{"type":"Scorpion Empathy","kind":"Ex","details":"This ability functions as a druid's wild empathy ability, save that it works only on scorpions. A girtablilu gains a racial bonus on this check equal to its Hit Dice (normally +10). Scorpions are normally mindless, but this empathic communication imparts upon them a modicum of implanted intelligence, allowing girtablilus to train scorpions and use them as guardians (though it doesn't grant them skills or feats)."}],"description":"Girtablilus fiercely guard ancient places and treasures lost to history. Far from civilized eyes, they thrive and piously protect their charges with the aid of monstrously large scorpions that girtablilus keep as pets.\n\nAll girtablilus share a zeal for religion, although the objects of veneration vary from tribe to tribe. Some girtablilu tribes still serve long-forgotten deities, preserving the divinities' names and holy rituals. Others embrace religions derived from prehistoric worship, devoted to the idea of gods that once were or might never have been.\n\nGirtablilu leaders are clerics or oracles, and are responsible for the tribe's religious observances and laws. Tradition and service to the group are important. Those who violate tribal beliefs are killed or exiled into the harsh wasteland.\n\nGirtablilus believe that no sacrifice in life (including death in the service of the gods) goes unrewarded in the hereafter; this belief makes them fierce and fearless fighters.\n\nA girtablilu is 13 ft. long and weighs 800 pounds.","ecology":"","habitat_society":""},{"name":"Glass Golem","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"construct","init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":8,"ac_flat_footed":21,"ac_mods":"-1 Dex, +13 natural, -1 size","hp":96,"hd":"12d10+30","hdvalue":12,"fort":4,"ref":3,"will":4,"defensive_abilities":["reflect spells"],"dr":"5/adamantine","immunities":["magic","construct traits"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +16 (2d8+5 plus bleed)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bleed","details":"1d8"},{"type":"dazzling brightness"}],"strength":20,"dexterity":9,"wisdom":11,"charisma":1,"baseatk":12,"cmb":18,"cmd":27,"environments":["any land"],"organizations":["solitary","gang (2-5)"],"treasure":"none","description_visual":"This jagged construct of glass has a human's shape, save that one arm ends in a jagged hammer and another in a spike of glass.","group":"Golem","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Dazzling Brightness","kind":"Ex","details":"A glass golem in an area of bright light dazzles any creature within 30 ft. that sees it for 1 round (Fortitude DC 16 negates). Once a creature makes its save against this ability, it is immune to that golem's brightness for 24 hours. The DC is Constitution-based."},{"type":"Immune to Magic","kind":"Ex","details":"A glass golem is immune to any spell or spell-like ability that allows spell resistance. In addition, certain spells and effects function differently against a glass golem, as noted below. • A shatter spell damages a glass golem as if it were a crystalline creature. • A keen edge spell affects all of a glass golem's slam attacks as if they were slashing weapons. • A magical attack that deals cold damage slows a glass golem (as the slow spell) for 3 rounds (no saving throw). • A magical attack that deals fire damage ends any slow effect on the golem and heals 1 point of damage for each 3 points of damage the attack would otherwise deal. If the amount of healing would cause the golem to exceed its full normal hit points, it gains any excess as temporary hit points. A glass golem gets no saving throw against fire effects."},{"type":"Reflect Spells","kind":"Ex","details":"As a free action once every 1d4 rounds, a glass golem can align its internal structure to enhance its resistance to magic for 1 round. During this time, the golem reflects spells (even spells that function differently against the golem as described in its immune to magic ability) as if under the effect of a spell turning spell."}],"description":"A glass golem is a sizable guardian constructed by a powerful caster, usually in the shape of an armored humanoid. They are more common in desert lands where quartz-based sand is readily available, or in urban centers where glassblowing is commonplace.\n\nA typical glass golem is 10 ft. tall and weighs 2,500 pounds.\n\nStained Glass Golems (+0 CR): Divine casters sometimes build glass golems that resemble the windowpanes commonly found in temples. Thin and agile, these colorful beings often act as spies, wielding powers of stealth that their other counterparts don't possess. A stained glass golem has a +8 racial bonus on Stealth checks.\n\nConstruction\n\nA glass golem's body is made from 2,500 pounds of glass mixed with special salts and rare minerals worth 1,000 gp.\n\nGLASS GOLEM\n\nCL 10th; Price 33,000 gp (glass); 39,400 (stained glass)\n\nConstruction\n\nRequirements Craft Construct, animate objects, flame strike, geas/ quest, spell turning, creator must be caster level 10th; Skill Craft (sculptures) DC 17; Cost 17,000 gp (glass golem); 20,200 gp (stained glass golem)","ecology":"","habitat_society":""},{"name":"Goliath Stag Beetle","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":8,"ac_flat_footed":21,"ac_mods":"+13 natural, -2 size","hp":104,"hd":"11d8+55","hdvalue":11,"fort":12,"ref":3,"will":3,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"poor"}],"melee":"bite +17 (3d8+16)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"trample","details":"3d8+16, DC 26"}],"strength":32,"dexterity":10,"constitution":21,"wisdom":10,"charisma":4,"baseatk":8,"cmb":21,"cmd":31,"cmd_special":"+8 vs. trip","skills":[{"skill":"Fly","value":-8}],"environments":["warm forests","warm plains"],"organizations":["solitary","pair","herd (3-8)"],"treasure":"none","description_visual":"This massive beetle is the size of a small house. Its immense, horn-like mandibles clash with a hungry fervor.","group":"Beetle","source":"PFRPG Bestiary 2","description":"Making its home in tropical and subtropical forests across the globe, the goliath beetle is among the largest species of giant beetle. While its diminutive cousins are primarily herbivores, the goliath stag beetle is carnivorous, hunting herd animals, humanoids, and even giants with ease. They typically use their trample attack against creatures smaller than themselves, returning after this punishing assault to pick off anything that's still moving with swift and deadly bites.\n\nA goliath stag beetle is 25 ft. long and weighs 8,000 pounds.","ecology":"","habitat_society":""},{"name":"Gorgon","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":20,"ac_touch":9,"ac_flat_footed":20,"ac_mods":"+11 natural, -1 size","hp":100,"hd":"8d10+56","hdvalue":8,"fort":13,"ref":6,"will":7,"speed":[{"type":"land","speed":30}],"melee":"gore +14 (2d8+7), 2 hooves +9 (1d6+3)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"60-foot cone, turn to stone, Fortitude DC 21 negates"},{"type":"trample","details":"2d8+10, DC 21"}],"strength":24,"dexterity":10,"constitution":24,"intelligence":2,"wisdom":16,"charisma":9,"baseatk":8,"cmb":16,"cmd":26,"feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":17}],"environments":["any hills","temperate plains","any underground"],"organizations":["solitary","pair","pack (3-4)","herd (5-12)"],"treasure":"none","description_visual":"This bull-like creature seems to be made of interlocking metallic plates. Faint plumes of green smoke puff from its mouth.","source":"PFRPG Bestiary","special_abilities":[{"type":"Breath Weapon","details":"A gorgon can use its breath weapon once every 1d4+1 rounds to create a 60-foot cone of green gas. Those caught in the area of the gas can attempt a DC 21 Fortitude save to resist the effects, but those who fail the save are immediately petrified. This petrification is temporary-each round, a petrified creature can attempt a new DC 21 Fortitude save to recover from the petrification as long as it isn't caught within the area of effect of the gorgon's breath weapon a second time while petrified. A creature exposed to the gorgon's breath a second time while already petrified becomes permanently petrified, and can no longer attempt to make additional Fortitude saves to recover naturally. The save DC is Constitution-based."}],"description":"Gorgons are magical, foul-tempered creatures-while they might appear to be constructs at first glance, beneath their artificallooking armor plates they are made of flesh and bone. Like aggressive bulls, they challenge any unfamiliar creature they encounter, often trampling their opponent's corpse or shattering its stony remnants until the creature is unrecognizable. The females are just as dangerous as the males, and the two sexes appear identical. A typical gorgon stands 6 ft. tall and 8 ft. long. It weighs 4,000 pounds. Gorgons derive nutrients from the consumption of minerals, particularly the stone of their petrified victims, and any statues they create are likely to be gnawed thoroughly. They cannot digest metal or gems, so their dung (which resembles bitter-smelling gray powder) often contains small, raw crystals and nuggets of ore. Their aggression toward all other creatures means that there are few to no predators or other prey animals in their grazing grounds. Each herd is led by a dominant bull; solitary gorgons are usually adolescent bulls driven out of their herd by the lead bull. Their flesh is tough but beefy (once the armored hide is removed), and to those who acquire the taste, quite filling. Many stone giant tribes believe eating gorgon meat enhances their own natural armor. Powdered gorgon horn is worth 250 gp as an alternate material component for magic items using bull's strength, stoneskin, flesh to stone, statue, and similar magic.","ecology":"","habitat_society":""},{"name":"Gray Render","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":21,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+1 Dex, +11 natural, -1 size","hp":100,"hd":"8d10+56","hdvalue":8,"fort":13,"ref":7,"will":4,"speed":[{"type":"land","speed":30}],"melee":"bite +14 (2d6+7), 2 claws +15 (1d8+7 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d8+10"}],"strength":25,"dexterity":13,"constitution":24,"intelligence":3,"wisdom":14,"charisma":8,"baseatk":8,"cmb":16,"cmb_special":"+4 vs. grapple","cmd":27,"feats":[{"feat":"Awesome Blow"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Perception","value":13},{"skill":"Survival","value":6}],"languages":["Giant"],"sq":[{"type":"double damage against objects"}],"environments":["temperate marshes"],"organizations":["solitary (plus bonded creatures if any)"],"treasure":"incidental","description_visual":"This hulking beast has slick, gray, hairless skin. Its numerous yellow eyes and wide toothy maw are its only facial features.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Double Damage Against Objects","kind":"Ex","details":"A gray render that makes a full attack against an object or structure deals double damage."}],"description":"Standing over 9 ft. tall and weighing in excess of 4,000 pounds, a gray render is a solitary and savage predator. Renders are gifted with immense strength, and some reports claim to have witnessed a gray render uprooting a fully grown tree and tearing it to splinters in order to catch prey hiding within.\n\nGray renders actively avoid forming groups or communities with their own kind, and perhaps only tolerate the presence of other renders when it is time to mate. Some sages claim they are asexual, but it is more likely they are hermaphrodites able to self-fertilize, and reproduce only rarely.\n\nDespite its solitary existence, a gray render often develops an affectionate bond with other creatures, typically a herd of herbivores or a small tribe of humanoids, but in some cases a solitary denizen of its swamp. The render acts as a guardian for this creature or creatures, never straying more than a mile away, running to protect them if they are attacked, and providing an offering of meat once each day, as might a domesticated cat. A gray render never harms its protected creatures, and retreats in confusion if they attack it. Most animal \"pets\" grow to accept its presence, and primitive humanoid \"pets\" often believe their guardian is a sign of favor from the gods. A render's bond may last from a few months to as long as 10 years, after which it wanders to a new territory and ignores its former favorites.\n\nRenders are generally not malicious, and only attack if hungry or if they or their pets are threatened. A render protecting its pets fights to the death.","ecology":"","habitat_society":""},{"name":"Greater Shadow","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":18,"ac_flat_footed":12,"ac_mods":"+2 deflection, +5 Dex, +1 dodge","hp":58,"hd":"9d8+18","hdvalue":9,"fort":5,"ref":8,"will":7,"defensive_abilities":["incorporeal","channel resistance +2"],"immunities":["undead traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"incorporeal touch +11 (1d8 Strength)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn","details":"as per shadow"},{"type":"strength damage"}],"dexterity":20,"intelligence":6,"wisdom":12,"charisma":15,"baseatk":6,"cmb":11,"cmd":24,"feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Mobility"},{"feat":"Skill Focus (Perception, Stealth)"}],"skills":[{"skill":"Fly","value":15},{"skill":"Perception","value":13},{"skill":"Stealth","value":20,"special":"+24 in dim light, +16 in bright light"}],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"This shadowy figure sways and moves with an erratic grace, as if lit by an unseen fire.","group":"Shadow","source":"PFRPG Bestiary","special_abilities":[{"type":"Strength Damage","kind":"Su","details":"A greater shadow's touch deals 1d8 points of Strength damage to a living creature. This is a negative energy effect. A creature dies if this Strength damage equals or exceeds its actual Strength score."}],"description":"Greater shadows are those undead shadows that have come to be particularly infused with negative energy, such as those that have spent vast lengths of time in areas of the Plane of Shadow awash in negative energy, or those that have drained the lives of thousands of victims. These undead monsters are often found with a small band of normal shadows, which typically treat a greater shadow as a leader to rally behind.","ecology":"","habitat_society":""},{"name":"Guecubu","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"undead","subtypes":["earth"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"auras":["broken ground (30 ft., DC 20)"],"ac":21,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+4 Dex, +1 dodge, +6 natural","hp":104,"hd":"11d8+55","hdvalue":11,"hp_mods":["fast healing 5"],"fort":8,"ref":7,"will":11,"defensive_abilities":["channel resistance +2"],"dr":"5/bludgeoning","immunities":["electricity","undead traits"],"resists":[{"type":"cold","value":10}],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":15}],"speed_mod":"earth glide","melee":"bite +14 (1d8+6 plus misfortune), 2 slams +14 (1d6+6 plus misfortune)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"stone shape"}]},{"frequency":"1/day","spells":[{"spell":"spike stones"},{"spell":"transmute mud to rock"},{"spell":"transmute rock to mud"}]},{"frequency":"3/day","spells":[{"spell":"soften earth and stone"},{"spell":"spike growth"}]}],"strength":22,"dexterity":18,"intelligence":13,"wisdom":18,"charisma":21,"baseatk":8,"cmb":14,"cmd":29,"feats":[{"feat":"Combat Expertise"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Whirlwind Attack"}],"skills":[{"skill":"Acrobatics","value":15},{"skill":"Knowledge (nature)","value":12},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Stealth","value":18}],"languages":["Abyssal","Common"],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"A skeletal carcass pulls itself from the ground, its body formed as much from earth and soil as from bones and rotting flesh.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Broken Ground","kind":"Su","details":"The ground in a 30-foot radius around a guecubu ripples and shudders unnaturally. This transforms the area surrounding a guecubu into difficult terrain. A guecubu can move through this area with no penalty. Consecrated ground cannot be affected by this ability, nor can any area warded by a magic circle against chaos or a magic circle against evil."},{"type":"Misfortune","kind":"Su","details":"A creature struck by a guecubu must make a DC 20 Will save or become permanently cursed with misfortune. The victim of this curse takes a -4 penalty on all attack rolls, saving throws, and skill checks, and any critical threat against the victim automatically confirms. If a guecubu hits a creature already suffering from this curse, the victim must make a DC 20 Will save or be staggered for 1 round. This is a curse effect. The save DC is Charisma-based."}],"description":"Often when a particularly evil criminal is executed, suspicious folk fear that the criminal's remains might rise from death to continue to plague the living. To combat this possibility, many mobs or rural justices take to the practice of burning the bodies, grinding the bones, and scattering the remains in the wild. Yet in the case of particularly evil criminals, even these steps are in vain, for their will is enough to reassemble a body from earth, stone, roots, and plants drawn from the region into which the remains were scattered. Such an undead horror rises as a guecubu, a harbinger of misfortune and vengeance from beyond the grave.\n\nA newly formed guecubu remembers well how its enemies treated it, and while the undead creature retains none of its previous life's talents, its undead state grants it many new tools to seek revenge with. Typically, a guecubu doesn't limit its revenge to those directly involved with its execution-entire villages and towns fall victim to its rage. The guecubu's tactics tend toward the subtle, and it seeks to spread misfortune and death on a person-by-person basis, slaying its enemies one at a time until they flee, so that all that remains is a ghost town.\n\nA guecubu is 6 ft. tall and weighs 100 pounds.","ecology":"","habitat_society":""},{"name":"Gynosphinx","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+1 Dex, +11 natural, -1 size","hp":102,"hd":"12d10+36","hdvalue":12,"fort":11,"ref":9,"will":10,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"2 claws +17 (2d6+6/19-20)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +17, 2d6+6"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"comprehend languages"},{"spell":"detect magic"},{"spell":"read magic"},{"spell":"see invisibility"}]},{"frequency":"1/day","spells":[{"spell":"dispel magic"},{"spell":"legend lore"},{"spell":"locate object"},{"spell":"remove curse"}]},{"frequency":"3/day","spells":[{"spell":"clairaudience/clairvoyance"}]},{"frequency":"1/week","spells":[{"spell":"symbol of fear","details":"any one of the following"},{"spell":"symbol of pain"},{"spell":"symbol of persuasion"},{"spell":"symbol of sleep"},{"spell":"symbol of stunning","details":"all symbols last for 1 week maximum"}]}],"strength":22,"dexterity":13,"constitution":16,"intelligence":18,"wisdom":19,"charisma":19,"baseatk":12,"cmb":19,"cmd":30,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Casting"},{"feat":"Hover"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":14},{"skill":"Fly","value":7},{"skill":"Intimidate","value":14},{"skill":"Knowledge (any two)","value":6},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":12}],"languages":["Common","Draconic","Sphinx"],"environments":["warm deserts","warm hills"],"organizations":["solitary","pair","cult (3-6)"],"treasure":"double","description_visual":"This creature has the body of a lion, the wings of a falcon, and the head and torso of a beautiful human woman.","group":"Sphinx","source":"PFRPG Bestiary","description":"Although there are many different species of sphinx, the one certain scholars refer to as the \"gynosphinx\" (a name many sphinxes find insulting) is a wise and majestic creature that is nevertheless terrifying when angered. Less moralistic than their male counterparts (the \"androsphinx\"-a different creature entirely than the sphinx presented here), sphinxes are careful and methodical in their decision-making, and pride themselves on their cold logic and impartiality.\n\nThey have little patience for the lesser sphinx variants, seeing them as little better than animals. Sphinxes love riddles and complicated dilemmas, and treasure strange facts and arcane trivia far more than gold or gems While not great scholars in any traditional sense, sphinxes' great appreciation of puzzles leads them to research shallowly in a wide variety of subjects, and they can often be invaluable sources of information, especially when making use of their magical abilities. They are usually happy to barter with other races, and regularly trade material goods for information or new and interesting quandaries. They make excellent guardians for temples, tombs, and other important locations, so long as they are kept adequately entertained. Sphinxes place great value on politeness, but can be dangerously temperamental-while they may decide to share their latest riddles with travelers out of altruism, they think little of devouring those who don't give their dilemmas adequate attention or provide useful insight.\n\nSphinxes are typically 10 ft. long and about 800 pounds. While their wings are capable of holding them aloft for long periods of time, they are poor fliers, and prefer to land before engaging foes, lashing out with their powerful claws. Though fiercely territorial, they tend to give intruders plenty of warning before attacking.","ecology":"","habitat_society":""},{"name":"Hellwasp Swarm","cr":8,"xp":4800,"alignment":"LE","size":"Diminutive","type":"vermin","subtypes":["extraplanar","swarm"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":21,"ac_flat_footed":14,"ac_mods":"+6 Dex, +1 dodge, +4 size","hp":90,"hd":"12d8+36","hdvalue":12,"fort":10,"ref":10,"will":7,"dr":"10/good","immunities":["swarm traits","weapon damage"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":5},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"swarm (3d6 plus distraction and poison)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 18"},{"type":"inhabit"}],"strength":1,"dexterity":22,"constitution":14,"intelligence":6,"wisdom":13,"charisma":9,"baseatk":9,"feats":[{"feat":"Ability Focus (poison)"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":25},{"skill":"Perception","value":4},{"skill":"Stealth","value":24}],"languages":["Infernal"],"environments":["any (Hell)"],"organizations":["solitary","pair","infestation (3-6)"],"treasure":"incidental","description_visual":"This hideous, buzzing cloud of insects is comprised of black and yellow wasps with hungry red eyes.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Inhabit","kind":"Ex","details":"A hellwasp swarm can enter the body of a helpless or dead creature by crawling into its mouth and other orifices. Inhabiting a body requires 1 minute, and the victim must be Small, Medium, or Large. The swarm can abandon the body at any time as a full-round action. Any attack against the host deals half damage to the hellwasp swarm as well, although the swarm's DR, resistances, and immunities may negate some or all of this damage. When a hellwasp swarm inhabits a dead body, it effectively transforms the corpse into a zombie of the appropriate size under the swarm's control. If a hellwasp swarm inhabits a living victim, it can neutralize the effects of its own poison and control the victim's movement and actions as if using dominate monster. Hellwasps quickly consume a living victim, dealing 2d4 points of Constitution damage per hour. A hellwasp-inhabited creature is easy to spot, since its skin crawls with the forms of the insects inside. A swarm can attempt a Disguise check to conceal its inhabitation of a host, with a -4 penalty if currently inhabiting a Small host. A remove disease or heal spell cast on an inhabited victim forces the hellwasp swarm to abandon its host."},{"type":"Poison","kind":"Ex","details":"Swarm-injury; save Fort DC 20; frequency 1/round for 6 rounds; effect 1d6 Dex; cure 2 consecutive saves."}],"description":"Even Hell's fiendish inhabitants know to stay clear of the maddening buzz of hellwasp swarms. While individual hellwasps are mindless, when swarmed together they gain a hive mind that torments the living and the dead alike. Sages and diabolists argue as to why this happens, but a favored explanation is that all hellwasps contain the dispersed soul of some greater devil, scattered and imprisoned by his rivals for infractions lost to mortal knowledge.\n\nThough intelligent, these swarms are often difficult to understand and reason with. A hellwasp swarm can speak in a fashion with its myriad droning wings. The chatter is often little more than repetitive mantras of insults and the voicing of the twisted and base desires of the swarm. A hellwasp swarm has little use for reason, diplomacy, or discourse in other circumstances, for its desires are as savage as its home plane.","ecology":"","habitat_society":""},{"name":"Hydrodaemon","cr":8,"xp":4800,"alignment":"NE","size":"Large","type":"outsider","subtypes":["aquatic","daemon","evil","extraplanar"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"}],"ac":20,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+2 Dex, +9 natural, -1 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":11,"ref":9,"will":2,"dr":"10/cold iron or silver","immunities":["acid","death effects","disease","poison","waters of the River Styx"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":19,"speed":[{"type":"land","speed":30},{"type":"fly","speed":40,"special":"see glide below","maneuverability":"average"},{"type":"swim","speed":60}],"melee":"bite +13 (1d8+4 plus grab), 2 claws +13 (1d6+4)","ranged":"sleep spittle +11 (sleep)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rake","details":"2 claws +13, 1d6+4"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"water walk"}]},{"frequency":"at-will","spells":[{"spell":"acid arrow"},{"spell":"deeper darkness"}]},{"frequency":"1/day","spells":[{"spell":"desecrate"},{"spell":"summon","details":"level 3, 1 hydrodaemon 50%"}]},{"frequency":"3/day","spells":[{"spell":"control water"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"summon monster V","details":"Large water elemental only"}]}],"strength":18,"dexterity":15,"constitution":18,"intelligence":9,"wisdom":11,"charisma":14,"baseatk":10,"cmb":12,"cmd":24,"feats":[{"feat":"Cleave"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":0},{"skill":"Intimidate","value":14},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":10},{"skill":"Swim","value":21}],"languages":["Abyssal","Infernal","telepathy 100 ft."],"sq":[{"type":"amphibious"},{"type":"glide"}],"environments":["any (Abaddon)"],"organizations":["solitary","gang (2-5)","mob (6-12)"],"treasure":"standard","description_visual":"The skin on this frog-like fiend is clammy and its eyes look dead and milky; its wide face is split by a fanged maw.","group":"Daemon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Glide","kind":"Ex","details":"A hydrodaemon can launch itself into the air and glide along for 1 minute, gaining a fly speed of 40 ft. with average maneuverability. While gliding, the hydrodaemon gains the pounce ability."},{"type":"Sleep Spittle","kind":"Su","details":"A hydrodaemon can spit at a single target within 20 ft., making a ranged touch attack as a standard action. A target hit by this spittle must succeed on a DC 19 Will save or fall asleep for 6 rounds. The save DC is Constitution-based."}],"description":"While at first glance these creatures seem like enormous and foul boggards, their dangerous gait, dead eyes, and wicked claws give away their fiendish nature. In their home environment, hydrodaemons swim the sickening rivers and seas of Abaddon and the River Styx, ducking beneath the rivers of pus and bile only to leap out at enemies and rend their flesh with tooth and claw. It is said these are among the few creatures able to survive in the deadly waters of the River Styx. When called to the Material Plane, hydrodaemons serve powerful spellcasters, protecting domains dotted with pools, streams, and even sewer complexes. Associated with death by drowning, these fiends use a favored tactic to draw the most anguish from their victims. Hydrodaemons first attack with their inky black sleep spittle, hoping to render victims unconscious. With their opponents unable to fight back, hydrodaemons drag their enemies into the foul waters they call home and delight as the liquid fills their victims' gasping lungs. If unable to drown a victim, they finish the job with jaws and claws.\n\nHydrodaemons possess an awkward gait, springing back on their heels and leaping about like humanoid frogs. Even so, they move in an unpredictable manner, twisting their bodies with each hopping movement. Hydrodaemons can also unfurl flaps of skin that allow them to glide through the air. Hydrodaemons stand 10 ft. tall and weigh upward of 3,000 pounds.","ecology":"","habitat_society":""},{"name":"Iku-Turso","cr":8,"xp":4800,"alignment":"NE","size":"Medium","type":"aberration","subtypes":["aquatic"],"init":7,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":14,"ac_flat_footed":17,"ac_mods":"+3 Dex, +1 dodge, +7 natural","hp":102,"hd":"12d8+48","hdvalue":12,"fort":8,"ref":9,"will":11,"immunities":["disease"],"weaknesses":["light blindness"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":60}],"melee":"bite +16 (1d8+7 plus disease), 2 claws +16 (1d6+7)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"light lure"}],"strength":24,"dexterity":16,"constitution":19,"intelligence":7,"wisdom":12,"charisma":17,"baseatk":9,"cmb":16,"cmd":30,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Perception","value":12},{"skill":"Stealth","value":14},{"skill":"Survival","value":12},{"skill":"Swim","value":15}],"languages":["Aklo","Aquan","Undercommon"],"sq":[{"type":"amphibious"}],"environments":["cold underground","cold water","temperate underground","temperate water"],"organizations":["solitary","pair","cell (3-8)"],"treasure":"standard","description_visual":"This grotesque, emerald-scaled creature resembles a crossbreed of an eel, a viperfish, and a clawed humanoid.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Disease","kind":"Su","details":"An iku-turso's bite inflicts a strange, supernatural disease called tursas. This disease causes the victim's skin to grow painfully scaly, causes strange hallucinations, and eventually transforms the victim into an iku-turso. Tursas: Bite-injury; save Fort DC 20; onset 1 minute; frequency 1/day; effect 1d3 Wis damage and 1d6 Cha drain; cure 2 consecutive saves. As long as a victim suffers any ability damage from tursas, it gains the ability to breathe water. A creature reduced to 0 Charisma by this disease transforms into a fully grown and healthy iku-turso-it immediately forgets its previous life and abilities and seeks out the nearest iku-turso community to join it. A wish or miracle can reverse this transformation. The save DC is Constitution-based."},{"type":"Light Lure","kind":"Su","details":"As a standard action, an iku-turso can call forth a few small points of light, functioning like a dancing lights spell (CL equals the iku-turso's HD) except as described here. Creatures within 100 ft. of one of these lights must make a DC 19 Will save upon sighting them or be compelled to approach them by the safest and most direct path. A creature that successfully saves is immune to the same iku-turso's light lure for 24 hours. If a subject of this effect has to move through hazardous terrain to reach the lights, that subject receives another saving throw to end the effect before entering the hazardous terrain. This effect ends once the character reaches the light or takes any form of damage. This is a visual mind-affecting charm effect. The save DC is Charisma-based."}],"description":"Iku-tursos are hideous denizens of the deep sea. There, they venerate sinister gods of plague and contagion and torment victims plucked from ship and shore in special air-filled torture chambers. Disease is sacred to the iku-tursos, and those who suffer from sickness are considered blessed-an iku-turso often chooses to leave obviously diseased victims to their fates rather than attempt to capture them.","ecology":"","habitat_society":""},{"name":"Immense Tortoise","cr":8,"xp":4800,"alignment":"N","size":"Colossal","type":"animal","init":-2,"senses":[{"type":"low-light vision"}],"ac":25,"ac_touch":0,"ac_flat_footed":25,"ac_mods":"-2 Dex, +25 natural, -8 size","hp":126,"hd":"11d8+77","hdvalue":11,"fort":16,"ref":5,"will":3,"speed":[{"type":"land","speed":20}],"melee":"bite +15 (4d6+22/19-20)","space":"30 ft.","reach":"30 ft.","special_attacks":[{"type":"trample","details":"2d8 + 22, DC 30"}],"strength":40,"dexterity":7,"constitution":24,"intelligence":2,"wisdom":11,"charisma":9,"baseatk":8,"cmb":31,"cmd":39,"cmd_special":"+4 vs. trip","feats":[{"feat":"Critical Focus"},{"feat":"Endurance"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (bite)"},{"feat":"Improved Great Fortitude"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":14,"special":"+10 for sound-based checks"}],"sq":[{"type":"buoyant"},{"type":"shell"},{"type":"slow and steady","details":"see giant tortoise"}],"environments":["warm islands"],"organizations":["solitary"],"treasure":"none","description_visual":"Plants and even trees grow atop the shell of this massive tortoise, which gazes about with dull, placid eyes.","group":"Tortoise","source":"PFRPG Bestiary 4","description":"These immense, ancient tortoises never stop growing.","ecology":"","habitat_society":""},{"name":"Incutilis Lord","cr":8,"xp":4800,"alignment":"NE","size":"Large","type":"aberration","subtypes":["aquatic"],"init":3,"senses":[{"type":"all-around vision"},{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+3 Dex, +10 natural, -1 size","hp":104,"hd":"11d8+55","hdvalue":11,"fort":9,"ref":6,"will":12,"immunities":["disease","mind-affecting effects","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10},{"type":"swim","speed":40}],"speed_mod":"jet 120 ft.","melee":"4 tentacles +14 (1d6+2 plus calcifying sting)","space":"10 ft.","reach":"15 ft.","strength":20,"dexterity":17,"constitution":18,"intelligence":15,"wisdom":16,"charisma":15,"baseatk":8,"cmb":14,"cmd":27,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Toughness"},{"feat":"Weapon Focus (tentacle)"}],"skills":[{"skill":"Climb","value":18},{"skill":"Intimidate","value":13},{"skill":"Knowledge (arcana)","value":6},{"skill":"Knowledge (local)","value":6},{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":12},{"skill":"Spellcraft","value":12},{"skill":"Stealth","value":11},{"skill":"Survival","value":11},{"skill":"Swim","value":21}],"languages":["Aklo","Aquan","Common","telepathy 100 ft."],"sq":[{"type":"amphibious"},{"type":"black coral secretion"},{"type":"calcified minion"}],"environments":["any oceans"],"organizations":["solitary","pair","coven (1-2 incutilis lords plus 3-7 incutilises)"],"treasure":"standard (giant red pearl worth 500 gp)","description_visual":"A curved shell protects an unsightly mass of barbed tentacles, ringed by numerous inhuman eyes.","source":"Plunder & Peril","special_abilities":[{"type":"Black Coral Secretion","kind":"Ex","details":"An incutilis lord's tentacles generate an oily black residue that quickly hardens into a dense, coral-like substance. A single application covers a 5 foot square and completely hardens in 1 minute, even when exposed to water. This substance is malleable until hardened, allowing an incutilis lord or the lord's minions to shape it into armor, walls, and more. Once calcified, it has a hardness of 4 and 8 hit points per inch of thickness. An incutilis lord can produce one application of black coral per Hit Die each day."},{"type":"Calcified Minion","kind":"Su","details":"A calcifying stinger imparts a strong psychic connection between a calcified target and the incutilis lord who implanted the stinger. Once the target succumbs to the incutilis lord's will (see the calcifying sting ability, below), the target's whole body is infused with new secretions that allow the incutilis lord to dictate the target's actions and restore any Dexterity lost to the calcifying sting, as the secretions assist the minion's movement rather than hindering it. The incutilis lord can control a number of minions equal to its Charisma modifier as a free action. If the incutilis lord attempts to control a new minion in excess of this limit, it must first release one of its current calcified minions; see the calcifying sting ability, below. The minions have no will of their own but retain a small portion of their identity, giving the incutilis lord access to their feats, physical skills, extraordinary abilities, spell-like abilities, and supernatural abilities. A calcified creature moves under the direct control of its incutilis lord until the stinger is removed from its body. While under the incutilis lord's control, a calcified minion takes its own normal actions each round, as directed by its controller. A minion can survive this process for a number of days equal to its Constitution score. After this time, the calcified minion dies, though its body retains a semblance of life. The dead minion is treated as a living creature and can be controlled in the same fashion as before until the calcifying stinger is removed or the incutilis lord that controls the creature dies."},{"type":"Calcifying Sting","kind":"Su","details":"The tentacles of an incutilis lord inject a painful stinger that constantly generates a black coral secretion. A creature stung by an incutilis lord must attempt a DC 19 Fortitude saving throw at the beginning of every turn until the stinger is removed. Each time it fails this save, the creature takes an additional 1d6 points of damage and 2 points of Dexterity drain. If this causes the creature to reach 0 or fewer hit points or a Dexterity score of 0, it loses all will of its own and immediately comes under the control of the incutilis lord (see the calcified minion ability, above). As a swift action, the incutilis lord can psychically command one of its stingers to remove itself from a stung creature, releasing its control over that creature. Another creature can forcefully remove a stinger from a willing or unconscious target by a succeeding at a DC 19 Heal check. Regardless of whether this Heal check succeeds or fails, attempting to remove the stinger deals 1d8 points of damage to the target. If the stinger is removed or the incutilis lord dies, the fluid seeps out of the controlled creature's wounds and the creature is released from the incutilis lord's control-though the creature may be dead by that time. The save DC is Constitution-based."}],"description":"The elders of the incutilis race display an unearthly beauty, with vibrant colors and considerable aquatic grace for their size. As these horrors live for hundreds of years in remote aquatic locations, scholars remain unsure whether the lesser incutilises eventually attain this majestic form or are a separate race, and-more worrying-what their relationship is with these ancient aberrations of the deep ocean and the great subterranean seas.\n\nIncutilis lords attack with barbed tentacles, inflicting a painful sting and injecting a calcifying agent that transforms living tissue into a dense black growth resembling a cross between chitin and coral. The stinger anchors the incutilis lord's senses in a calcified minion, leaving a disturbing exoskeleton that moves the minion about at the monster's whim. Unlike the mindless zombies that serve a more common incutilis, an incutilis lord's servitors retain muscle memory and a grasp of their magical abilities. An incutilis lord can survive for decades by feeding on the body and psyche of a single Medium-sized victim, but rarely settles for having only one minion to manipulate or feed upon.\n\nAn incutilis lord's shell is about 8 ft. in diameter, and the aberration measures nearly 20 ft. long from the back of the shell to the tips of its longest tentacles. An incutilis lord weighs about 600 pounds.","ecology":"","habitat_society":""},{"name":"Intellect Devourer","cr":8,"xp":4800,"alignment":"CE","size":"Small","type":"aberration","init":10,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"detect magic"}],"ac":22,"ac_touch":17,"ac_flat_footed":16,"ac_mods":"+6 Dex, +5 natural, +1 size","hp":84,"hd":"8d8+48","hdvalue":8,"fort":7,"ref":8,"will":8,"dr":"10/adamantine and magic","immunities":["fire","mind-affecting effects"],"resists":[{"type":"cold","value":20},{"type":"electricity","value":20},{"type":"sonic","value":20}],"sr":23,"weaknesses":["vulnerability to protection from evil"],"speed":[{"type":"land","speed":40}],"melee":"4 claws +13 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"body thief"},{"type":"sneak attack","details":"+3d6"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"confusion","details":"single target only"},{"spell":"daze monster","details":"no HD limit"},{"spell":"inflict serious wounds"},{"spell":"invisibility"},{"spell":"reduce size","details":"as reduce person but self only"}]},{"frequency":"3/day","spells":[{"spell":"cure moderate wounds"},{"spell":"globe of invulnerability"}]}],"strength":12,"dexterity":23,"constitution":21,"intelligence":16,"wisdom":10,"charisma":17,"baseatk":6,"cmb":6,"cmd":22,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":19},{"skill":"Disguise","value":11},{"skill":"Knowledge (local)","value":14},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":29},{"skill":"Use Magic Device","value":11}],"languages":["Undercommon (cannot speak)","telepathy 100 ft."],"environments":["any underground"],"organizations":["solitary","brood (2-6)","tribe (7-16)"],"treasure":"double","description_visual":"Devoid of a head, or any features at all save for four short, clawed legs, this creature's body looks like a large, glistening brain.","source":"PFRPG Bestiary","special_abilities":[{"type":"Body Thief","kind":"Su","details":"As a full-round action that provokes an attack of opportunity, an intellect devourer can reduce its size, crawl into the mouth of a helpless or dead creature, and burrow into the victim's skull to devour its brain. This is a coup de grace attempt that inflicts 8d4+3d6+8 points of damage. If the victim is slain (or already dead), the intellect devourer usurps control of the body and may use it as its own, as if it controlled the target via a dominate monster spell. The intellect devourer has full access to all of the host's defensive and offensive abilities save for spellcasting and spell-like abilities (although the intellect devourer can still use its own spell-like abilities). A host body may not have been dead for longer than 1 day for this ability to function, and even successfully inhabited bodies decay to uselessness in 7 days (unless this time is extended via gentle repose). As long as the intellect devourer occupies the body, it knows (and can speak) the languages known by the victim and basic information about the victim's identity and personality, yet has none of the victim's specific memories or knowledge. Damage done to a host body doesn't harm the intellect devourer, and if the host body is slain, the intellect devourer emerges and is dazed for 1 round. Raise dead cannot restore a victim of body theft, but resurrection or more powerful magic can."},{"type":"Vulnerable to Protection from Evil","kind":"Ex","details":"An intellect devourer is treated as a summoned creature for the purpose of determining how it is affected by a protection from evil spell."}],"description":"Thought by some to be invaders from another dimension or planet, the sinister intellect devourers are certainly one of the world's cruelest races. Incapable of experiencing emotions or wallowing in the sins of physical pleasure on their own, intellect devourers are forced to steal bodies in order to indulge their gluttony, lust, and cruelty. Stories tell of entire cities of these creatures deep underground, where host bodies are worn like clothes to hideous orgies and vile feasts. Lone intellect devourers often dwell in ruins or caves on the edge of a civilized region so they can make periodic forays into town to \"shop\" for an attractive new body.\n\nAn intellect devourer is 3 ft. long and weighs about 60 pounds.","ecology":"","habitat_society":""},{"name":"Juvenile Black Dragon","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"dragon","subtypes":["water"],"init":6,"senses":[{"type":"dragon senses"}],"ac":24,"ac_touch":12,"ac_flat_footed":22,"ac_mods":"+2 Dex, +12 natural","hp":105,"hd":"10d12+40","hdvalue":10,"fort":11,"ref":9,"will":9,"immunities":["acid","paralysis","sleep"],"speed":[{"type":"land","speed":60},{"type":"fly","speed":150,"maneuverability":"average"},{"type":"swim","speed":60}],"melee":"bite +16 (1d8+7), 2 claws +15 (1d6+5), 2 wings +10 (1d4+2)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"60 ft. line, DC 20, 8d6 acid"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"darkness","details":"40 ft. radius"}]}],"strength":21,"dexterity":14,"constitution":19,"intelligence":12,"wisdom":15,"charisma":12,"baseatk":10,"cmb":15,"cmd":27,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":15},{"skill":"Handle Animal","value":11},{"skill":"Intimidate","value":14},{"skill":"Knowledge (arcana)","value":14},{"skill":"Perception","value":19},{"skill":"Stealth","value":21},{"skill":"Swim","value":26}],"languages":["Common","Draconic"],"sq":[{"type":"speak with reptiles"},{"type":"swamp stride"},{"type":"water breathing"}],"environments":["warm marshes"],"organizations":["solitary"],"treasure":"triple","description_visual":"Hissing green acid drips from the fanged maw of this black-scaled, horned dragon.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Speak with Reptiles","kind":"Sp","details":"A young or older black dragon gains the constant spell-like ability to speak with reptiles. This functions as speak with animals, but only with reptilian animals."},{"type":"Swamp Stride","kind":"Ex","details":"A very young or older black dragon can move through bogs and quicksand without penalty at its normal speed."},{"type":"Water Breathing","kind":"Ex","details":"A black dragon can breathe underwater indefinitely and can freely use its breath weapon, spells, and other abilities while submerged."}],"description":"Lording over the darkest swamps and marshes, black dragons are the undisputed masters of their domain, ruling through cruelty and intimidation. Those who dwell within a black dragon's reach live in fear. Black dragons tend to make their lairs in remote parts of the swamp, preferably in caves at the bottom of dark and fetid pools. Inside, they pile up their filthy treasure and sleep amid the roots and muck. Black dragons prefer their food a bit rotten and will often allow a meal to sit in a pool for days before consuming it. Black dragons prefer treasures that don't rot or decay, making their hoard, full of coins, gemstones, jewelry, and other objects made from stone or metal.","ecology":"","habitat_society":""},{"name":"Juvenile Brass Dragon","cr":8,"xp":4800,"alignment":"CG","size":"Medium","type":"dragon","subtypes":["fire"],"init":6,"senses":[{"type":"blindsense","modifier":"60 ft."},{"type":"dragon senses"}],"ac":24,"ac_touch":12,"ac_flat_footed":22,"ac_mods":"+2 Dex, +12 natural","hp":105,"hd":"10d12+40","hdvalue":10,"fort":11,"ref":9,"will":9,"immunities":["fire","paralysis","sleep"],"weaknesses":["Vulnerability to cold"],"speed":[{"type":"land","speed":60},{"type":"burrow","speed":30},{"type":"fly","speed":150,"maneuverability":"average"}],"melee":"bite +15 (1d8+7), 2 claws +15 (1d6+5), 2 wings +10 (1d4+2)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"breath weapon","details":"60-ft. line, DC 19, 8d4 fire"},{"type":"desert wind"},{"type":"sleep breath"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"endure elements"},{"spell":"speak with animals"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":3,"spellsknown_concentration":7,"spellsknown":[{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"comprehend languages"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"arcane mark"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"message"}]}],"strength":21,"dexterity":14,"constitution":19,"intelligence":14,"wisdom":15,"charisma":14,"baseatk":10,"cmb":15,"cmd":27,"cmd_special":"+4 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Spell Focus (Enchantment)"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Diplomacy","value":15},{"skill":"Fly","value":15},{"skill":"Heal","value":15},{"skill":"Linguistics","value":15},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":15}],"languages":["Common","Draconic","and 11 others"],"sq":[{"type":"Move Sand"}],"environments":["warm deserts"],"organizations":["solitary"],"treasure":"triple","description_visual":"A crest of horns sweeps back from the head of this dragon, leading to a long neck and serpentine brass body.","group":"Metallic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Desert Wind","kind":"Su","details":"A juvenile or older brass dragon can call up the desert wind to serve him. This functions as gust of wind, but any creature in its path must make a Fortitude save (DC 19) or be blinded for 1d4 rounds by the sand."},{"type":"Move Sand","kind":"Su","details":"A young or older brass dragon can move sand to excavate ruins or hide treasures. This functions as move earth, but it only affects sand. The dragon uses his HD in place of his caster level for this effect. This is equivalent to a 5th-level spell."},{"type":"Sleep Breath","kind":"Su","details":"Instead of a line of fire, a brass dragon can breathe a cone of sleep gas. Creatures within the cone must succeed on a Will save or fall asleep for 1d6+4 rounds."}],"description":"Consummate conversationalists, brass dragons prefer to talk instead of fight. Brass dragons lair near humanoid settlements, where they can hear the most recent news and gossip.","ecology":"","habitat_society":""},{"name":"Kuchrima","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"monstrous humanoid","init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":22,"ac_touch":16,"ac_flat_footed":16,"ac_mods":"+6 Dex, +6 natural","hp":104,"hd":"11d10+44","hdvalue":11,"fort":7,"ref":13,"will":6,"immunities":["disease","magic missile"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +16 (1d6+5 plus disease), 2 talons +16 (1d4+5)","ranged":"mwk Large composite longbow +18 (2d6+5/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"catastrophic shot"},{"type":"disease"}],"strength":20,"dexterity":22,"constitution":19,"intelligence":7,"wisdom":9,"charisma":10,"baseatk":11,"cmb":16,"cmb_special":"+4 vs. grapple","cmd":32,"feats":[{"feat":"Deadly Aim"},{"feat":"Improved Initiative"},{"feat":"Point-Blank Shot"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":24},{"skill":"Perception","value":19}],"languages":["Common","Giant","Thassilonian"],"sq":[{"type":"oversized weapon"}],"environments":["any mountains"],"organizations":["solitary","pair","flight (3-7)","gluttony (8-12)"],"treasure":"standard","description_visual":"This vaguely humanoid creature has a vulture's head and wings for arms, and wields an enormous bow in its taloned ft.","group":"Lamia-kin","source":"RotRL-AE-Appendix","special_abilities":[{"type":"Catastrophic Shot","kind":"Ex","details":"Whenever a kuchrima makes only a single attack in a round with a bow, it increases the critical threat range of that shot to 18-20."},{"type":"Disease","kind":"Ex","details":"Bite-Filth Fever; save Fort DC 19; onset 1d3 days; frequency 1/day; effect 1d3 Dex damage and 1d3 Con damage; cure 2 consecutive saves."},{"type":"Oversized Weapon","kind":"Ex","details":"A kuchrima can wield an oversized longbow in its talons while flying without incurring any penalty-this longbow can be one size category larger than normal (Large for most kuchrimas)."}],"description":"These foul creatures are a disgusting cross between humanoids and condors. Also known as the Eaters of the Dead, the kuchrimas are the lowest order of the lamia-kin, lacking even standard lamias' capability for spell-like abilities. They not only serve the function of common soldiers and scouts, but are also left to take care of the disposal of bodies, garbage, and other waste-most of which they feed upon. This habit results in their foul appearance and disease-ridden bite. Kuchrimas often wield giant bows in their powerful talons, holding the weapon in one talon and pulling the bowstring with the other in order to fire arrows with devastating effect.\n\nKuchrimas have much in common with the condors they resemble, and are opportunistic hunters and scavengers. Bands of kuchrima hunters might fly dozens of miles from their communal aerie, using their keen sight to locate prey both small and large. In the extreme mountainous areas they inhabit, such meals often take the form of giant rams, mountain aurochs, and even the occasional mountaineer, though these disgusting creatures prefer their meals dead and rotting.\n\nKuchrimas dwell principally in the thin air among the upper peaks of desolate mountain ranges, where they have gathered in enclaves or \"gluttonies.\" They have lived in a state of static barbarism since the diaspora following the fall of the Thassilonian Empire. In the thousands of years since that civilization's collapse, these lamia-kin have migrated to many mountainous regions throughout Golarion. These disease-ridden hunters strive to remain well out of sight of land-bound races, which they mistrust and fear in numbers. Should a new runelord or powerful harridan come into power and manage to locate these disparate gluttonies, however, the kuchrimas could be gathered into a formidable airborne force once again.","ecology":"","habitat_society":""},{"name":"Lamia Matriarch","cr":8,"xp":4800,"alignment":"CE","size":"Large","type":"monstrous humanoid","subtypes":["shapechanger"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+4 Dex, +8 natural, -1 size","hp":102,"hd":"12d10+36","hdvalue":12,"fort":7,"ref":12,"will":11,"immunities":["mind-affecting effects"],"sr":19,"speed":[{"type":"land","speed":40},{"type":"climb","speed":40},{"type":"swim","speed":40}],"melee":"+1 scimitars +14 (1d6+6/15-20 plus 1 Wisdom drain on first hit each round) or touch +16 (1d4 Wisdom drain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"Wisdom drain"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"ventriloquism"}]},{"frequency":"3/day","spells":[{"spell":"deep slumber"},{"spell":"dream"},{"spell":"major image"},{"spell":"mirror image"},{"spell":"suggestion"}]}],"spellsknown_caster_level":6,"spellsknown_concentration":9,"spellsknown":[{"spell_level":3,"spell_slots":4,"spells":[{"spell":"haste"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"death knell"},{"spell":"invisibility"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"cure light wounds"},{"spell":"divine favor"},{"spell":"mage armor"},{"spell":"magic missile"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"prestidigitation"}]}],"strength":20,"dexterity":19,"constitution":17,"intelligence":16,"wisdom":16,"charisma":21,"baseatk":12,"cmb":18,"cmd":32,"cmd_special":"can't be tripped","feats":[{"feat":"Double Slice"},{"feat":"Extend Spell"},{"feat":"Improved Critical (scimitar)"},{"feat":"Improved Two-Weapon Fighting"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (scimitar)"}],"skills":[{"skill":"Acrobatics","value":8,"special":"+12 jump"},{"skill":"Bluff","value":21},{"skill":"Climb","value":13},{"skill":"Diplomacy","value":11},{"skill":"Disguise","value":11},{"skill":"Intimidate","value":20},{"skill":"Knowledge (any one)","value":15},{"skill":"Knowledge (arcana)","value":15},{"skill":"Spellcraft","value":15},{"skill":"Swim","value":13},{"skill":"Use Magic Device","value":21}],"languages":["Abyssal","Common","Draconic"],"sq":[{"type":"change shape","details":"fixed Medium humanoid form, alter self"},{"type":"undersized weapons"}],"environments":["any land"],"organizations":["solitary","pair","cult (3-6)"],"treasure":"double (2 +1 scimitars)","description_visual":"This creature looks like a beautiful human woman from the waist up, but below is the body and tail of an immense snake.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Spells","details":"A lamia matriarch casts spells as a 6th-level sorcerer, and can cast spells from the cleric list as well as those normally available to a sorcerer. Cleric spells are considered arcane spells for a lamia matriarch."},{"type":"Wisdom Drain","kind":"Su","details":"A lamia matriarch drains 1d4 points of Wisdom each time she hits with her melee touch attack. The first time each round that she strikes a foe with a melee weapon, she also drains 1 point of Wisdom. A DC 21 Will save negates the Wisdom drain. Unlike with other kinds of ability drain attacks, a lamia matriarch doesn't heal damage when she uses her Wisdom drain. The save DC is Charisma-based."}],"description":"The queens of a race consumed by bitterness and predatory instinct, lamia matriarchs mastermind all manner of foul plots in hopes of breaking the bestial curse that aff licts their race. They move with shocking ease from silken-tongued temptresses to dervishes, striking with all the deadly precision of vipers. Quick to covet, enslave, and overindulge, lamia matriarchs luxuriate in gory feasts, violent trysts, and bloody entertainments, reveling until their playthings are broken or until they tire and move on.","ecology":"","habitat_society":""},{"name":"Lammasu","cr":8,"xp":4800,"alignment":"LG","size":"Large","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["magic circle against evil (20 ft.)"],"ac":21,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+1 Dex, +11 natural, -1 size","hp":94,"hd":"9d10+45","hdvalue":9,"fort":11,"ref":9,"will":8,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"2 claws +14 (1d8+6), 2 wings +9 (1d6+3)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +14; 1d8+6"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"dimension door"}]},{"frequency":"3/day","spells":[{"spell":"greater invisibility"}]}],"spellsknown_caster_level":7,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":4,"spells":[{"spell":"cure serious wounds"},{"spell":"searing light"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"cure moderate wounds"},{"spell":"lesser restoration"},{"spell":"resist energy"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"bless"},{"spell":"command"},{"spell":"cure light wounds"},{"spell":"detect evil"},{"spell":"divine favor"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"detect poison"},{"spell":"guidance"},{"spell":"mending"},{"spell":"purify food and drink"},{"spell":"resistance"},{"spell":"stabilize"}]}],"strength":23,"dexterity":12,"constitution":21,"intelligence":16,"wisdom":17,"charisma":14,"baseatk":9,"cmb":16,"cmd":27,"cmd_special":"+4 vs. trip","feats":[{"feat":"Blind-Fight"},{"feat":"Eschew Materials","type":"bonus"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Diplomacy","value":11},{"skill":"Fly","value":11},{"skill":"Knowledge (arcana)","value":12},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":12}],"languages":["Celestial","Common"],"environments":["temperate deserts"],"organizations":["solitary"],"treasure":"standard","description_visual":"This majestic creature has the body of a lion, the wings of an eagle, and the face of a wise human man.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Spells","details":"A lammasu casts spells as a 7th-level oracle, but doesn't gain any other class abilities possessed by an oracle. It ignores all divine focus material components for spells it casts."}],"description":"Lammasus are protectors of the weak and ever-vigilant champions against evil. These noble creatures dwell in crumbling desert ruins or other remote areas, where they tirelessly fight against the forces of darkness, hoping to defend those they consider lesser races from the evils that often lurk in such places.\n\nAlthough most of these winged sentinels prove wise and knowledgeable about those who would seek to do evil in their lands, many races find lammasus arrogant, dismissive, and patronizing, taking umbrage at their superior attitudes and affectations. Such reactions confuse and sometimes insult these highly honorable creatures, who seek only to do good and aid those weaker than themselves. Lammasus who witness members of other races actively combating evil typically prove more sensitive and address such allies as equals. Should good-aligned creatures prove their skill and overcome any differences of attitude they might have with one of these majestic beings, they find a true and noble ally and an invaluable resource for those hoping to defeat evil.\n\nLammasus are quite parental toward those who join their cause, bringing a lifetime of experience to any struggle. This often makes them stern, but those who know lammasus find them to be extremely caring about those they protect. A lammasu eagerly lays down its own life to protect those in peril if such a sacrifice might win the day. Most lammasus are 8 ft. in length and weigh approximately 900 pounds.","ecology":"","habitat_society":""}];
